var o = JSON.parse(value);
var m = o.version.match(/^(\d+\.\d+(?:\.\d+)?)/);
return o.id + ':' + (m ? m[1] : o.version_id);

var out = {};
value.split(/\r?\n/).forEach(function (line) {
    var m = line.match(/^([A-Z0-9_]+)=(.*)$/);
    if (!m) return;
    out[m[1]] = m[2].trim().replace(/^["']|["']$/g, '');
});
var codename = out.VERSION_CODENAME || out.UBUNTU_CODENAME || '';
if (!codename && out.VERSION) {
    var c = out.VERSION.match(/\(([^)]+)\)/);
    if (c) codename = c[1].split(' ')[0];
}
var id = (out.ID || 'unknown').toLowerCase();
var vid = out.VERSION_ID || '';
return JSON.stringify({
    id: id,
    id_like: out.ID_LIKE || '',
    name: out.NAME || '',
    version_id: vid,
    version: out.VERSION || '',
    codename: codename.toLowerCase(),
    pretty_name: out.PRETTY_NAME || '',
    id_major: id + ':' + vid.split('.')[0]
});
